const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centerCoords = ee.Geometry.Point(7.578886, 38.602260);
  const regionRadiusKm = 30;
  const geometry = centerCoords.buffer(regionRadiusKm * 1000); // Buffer in meters
  const year = 2022;
  const minLakeAreaSqKm = 25;

  // 2. Data Acquisition
  const jrcWater = ee.ImageCollection('JRC/GSW1_4/YearlyHistory')
    .filter(ee.Filter.eq('year', year))
    .first();

  // Check for empty collection (though JRC is global, so unlikely)
  if (jrcWater === null) {
    console.log("C1: No JRC water data found for the year 2022.");
    return;
  }

  // Select the water band and mask non-water pixels
  // Water values: 0=No water, 1=Seasonal, 2=Permanent
  const waterMask = jrcWater.select('water').gt(0); // Any water

  // Clip the water mask to the region of interest
  const waterInRegion = waterMask.clip(geometry);

  // Check if there are any water pixels at all within the region
  const totalWaterPixels = waterInRegion.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 30, // JRC data resolution
    maxPixels: 1e9
  }).get('water').getInfo();

  if (totalWaterPixels === 0) {
    console.log(`Water pixels in region: ${totalWaterPixels}`);
    console.log("C2: No water pixels found within the specified region.");
    return;
  }

  // 3. Processing - Identify connected water bodies and calculate area
  // Use connectedComponents to label distinct water bodies
  const connectedComponents = waterInRegion.connectedComponents({
    connectedness: ee.Image.connectedness8(),
    maxSize: 1024 // Max 1024 unique components, reasonable for lakes
  });

  // Calculate the area for each component.
  // The 'label' band contains the component ID.
  const pixelArea = ee.Image.pixelArea().mask(waterInRegion); // Only calculate area for water pixels

  // Use reduceRegion with a grouped reducer to sum pixel area for each component
  const componentAreas = pixelArea.addBands(connectedComponents.select('labels'))
    .reduceRegion({
      reducer: ee.Reducer.sum().group({
        groupField: 1, // Group by the 'labels' band
        groupName: 'component_id'
      }),
      geometry: geometry,
      scale: 30, // JRC data resolution
      maxPixels: 1e9
    });

  // Convert the result to a list of dictionaries
  const componentAreaList = ee.List(componentAreas.get('groups')).getInfo();

  if (!componentAreaList || componentAreaList.length === 0) {
    console.log("C2: No connected water bodies found.");
    return;
  }

  let largeLakeCount = 0;
  const minLakeAreaSqM = minLakeAreaSqKm * 1e6; // Convert km^2 to m^2

  console.log(`Year: ${year}, Region: ${regionRadiusKm}km radius, Min Lake Area: ${minLakeAreaSqKm} sq km`);
  console.log(`Total water pixels: ${totalWaterPixels}`);
  console.log(`Found ${componentAreaList.length} water bodies.`);

  // Iterate through component areas and count lakes larger than the threshold
  for (const group of componentAreaList) {
    const areaSqM = group.sum;
    if (areaSqM === null || typeof areaSqM !== 'number') {
      console.log(`C3: Calculation failure for a component area (value: ${areaSqM}).`);
      return;
    }
    const areaSqKm = areaSqM / 1e6;
    if (areaSqKm >= minLakeAreaSqKm) {
      largeLakeCount++;
      //console.log(`  - Large lake found, area: ${areaSqKm.toFixed(2)} km^2`);
    }
  }

  // 4. Validation & Final Answer
  console.log(`Number of lakes larger than ${minLakeAreaSqKm} sq km: ${largeLakeCount}`);

  if (largeLakeCount === null || isNaN(largeLakeCount)) {
    console.log("C3: Final lake count is invalid (null or NaN).");
  } else if (largeLakeCount > 2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
